//! The labs that ship with netrace, compiled in. They're generated by
//! `scripts/make-labs.py` into `labs/`; each has a scripted solution the
//! tests play through the CLI to prove it can be finished.

use netrace_doc::{Lab, Project};

/// A lab that ships with netrace.
#[derive(Debug, Clone, Copy)]
pub struct BundledLab {
    /// "07-vlans": the order and a stable name.
    pub id: &'static str,
    json: &'static [u8],
    /// The scripted answer (tests only; never shown to students).
    pub solution: &'static str,
}

impl BundledLab {
    /// A fresh copy of the starting topology, lab included.
    pub fn project(&self) -> Project {
        Project::from_json(self.json).expect("bundled labs are valid")
    }

    pub fn lab(&self) -> Lab {
        self.project()
            .lab()
            .cloned()
            .expect("bundled labs have a lab")
    }

    pub fn json(&self) -> &'static [u8] {
        self.json
    }
}

macro_rules! lab {
    ($id:literal) => {
        BundledLab {
            id: $id,
            json: include_bytes!(concat!("../../../labs/", $id, ".netrace/project.json")),
            solution: include_str!(concat!("../../../labs/", $id, ".solution")),
        }
    };
}

/// Every bundled lab, in teaching order.
pub fn bundled_labs() -> Vec<BundledLab> {
    vec![
        lab!("01-first-ping"),
        lab!("02-cabling"),
        lab!("03-default-gateway"),
        lab!("04-device-basics"),
        lab!("05-static-routes"),
        lab!("06-default-route"),
        lab!("07-vlans"),
        lab!("08-trunks"),
        lab!("09-router-on-a-stick"),
        lab!("10-stp-root"),
        lab!("11-ospf-single-area"),
        lab!("12-dhcp-server"),
        lab!("13-dhcp-relay"),
        lab!("14-acl-standard"),
        lab!("15-acl-extended"),
        lab!("16-nat-pat"),
        lab!("17-static-nat"),
        lab!("18-port-security"),
        lab!("19-ospf-troubleshooting"),
        lab!("20-layer3-switch"),
    ]
}
